// Postgres storage: one table per kind of record, in the `srijan` schema.
//
// Each row keeps the whole record in `data` (jsonb) — that is what the app reads and writes, so
// nothing is lost or reshaped on the way in and out. The other columns (name, email, status,
// dates…) are generated by Postgres from `data`, so the tables are easy to browse and query in
// Supabase but can never disagree with it. `ord` keeps records in the order they were added.
//
// Every request locks the single `srijan.meta` row first, so requests still run one at a time.
import postgres from "postgres";
import type { DB } from "@/lib/domain/types";

type Tx = postgres.TransactionSql;
type Collection = Exclude<keyof DB, "version" | "seq">;

const text = (k: string) => `(data->>'${k}')`;
const num = (k: string) => `((data->>'${k}')::numeric)`;
const bool = (k: string) => `((data->>'${k}')::boolean)`;
// Times are stored as milliseconds; show them as real timestamps.
const time = (k: string) => `to_timestamp((data->>'${k}')::double precision / 1000)`;

interface Table {
  name: string;
  /** Field that identifies a record. */
  key: string;
  /** Readable columns: [column, type, expression]. */
  columns: [string, string, string][];
}

// Keyed by DB field, so adding a collection to `DB` without a table here fails to compile.
const TABLES: Record<Collection, Table> = {
  users: {
    name: "users",
    key: "id",
    columns: [
      ["role", "text", text("role")],
      ["name", "text", text("name")],
      ["email", "text", text("email")],
      ["phone", "text", text("phone")],
      ["creator_id", "text", text("creatorId")],
      ["created_at", "timestamptz", time("createdAt")],
    ],
  },
  creators: {
    name: "creators",
    key: "id",
    columns: [
      ["name", "text", text("name")],
      ["user_id", "text", text("userId")],
      ["city", "text", text("cityId")],
      ["area", "text", text("zoneId")],
      ["verification", "text", text("verification")],
      ["available", "boolean", bool("available")],
      ["same_day_shoots", "boolean", bool("onDemand")],
      ["max_travel_km", "numeric", num("maxTravelKm")],
      ["jobs_done", "numeric", num("jobsDone")],
      ["upi_id", "text", text("upiId")],
      ["created_at", "timestamptz", time("createdAt")],
    ],
  },
  bookings: {
    name: "bookings",
    key: "id",
    columns: [
      ["code", "text", text("code")],
      ["status", "text", text("status")],
      ["client_id", "text", text("clientId")],
      ["creator_id", "text", text("creatorId")],
      ["package", "text", text("packageId")],
      ["city", "text", text("cityId")],
      ["area", "text", text("zoneId")],
      ["total", "numeric", num("total")],
      ["scheduled_at", "timestamptz", time("scheduledAt")],
      ["created_at", "timestamptz", time("createdAt")],
    ],
  },
  offers: {
    name: "offers",
    key: "id",
    columns: [
      ["booking_id", "text", text("bookingId")],
      ["creator_id", "text", text("creatorId")],
      ["kind", "text", text("kind")],
      ["status", "text", text("status")],
      ["distance_km", "numeric", num("distanceKm")],
      ["sent_at", "timestamptz", time("sentAt")],
      ["expires_at", "timestamptz", time("expiresAt")],
    ],
  },
  ledger: {
    name: "ledger",
    key: "id",
    columns: [
      ["type", "text", text("type")],
      ["amount", "numeric", num("amount")],
      ["booking_id", "text", text("bookingId")],
      ["campaign_id", "text", text("campaignId")],
      ["creator_id", "text", text("creatorId")],
      ["status", "text", text("status")],
      ["at", "timestamptz", time("at")],
    ],
  },
  campaigns: {
    name: "campaigns",
    key: "id",
    columns: [
      ["code", "text", text("code")],
      ["stage", "text", text("stage")],
      ["brand_name", "text", text("brandName")],
      ["contact_name", "text", text("contactName")],
      ["email", "text", text("email")],
      ["phone", "text", text("phone")],
      ["budget", "numeric", num("budget")],
      ["call_at", "timestamptz", time("callAt")],
      ["created_at", "timestamptz", time("createdAt")],
    ],
  },
  // Codes are stored only as hashes; the hash identifies each one.
  otps: {
    name: "sign_in_codes",
    key: "codeHash",
    columns: [
      ["email", "text", text("email")],
      ["attempts", "numeric", num("attempts")],
      ["sent_at", "timestamptz", time("sentAt")],
      ["expires_at", "timestamptz", time("expiresAt")],
    ],
  },
};

const ENTRIES = Object.entries(TABLES) as [Collection, Table][];

/** What was loaded, per table: key → the record as JSON. Saving writes only what changed. */
export type Snapshot = Map<Collection, Map<string, string>>;

const emptySnapshot = (): Snapshot => new Map(ENTRIES.map(([field]) => [field, new Map()]));

/**
 * Creates the schema and tables on first use. The `srijan` schema isn't exposed by Supabase's
 * public REST API, and row level security with no policies is a second lock. On the very first
 * run, data from the earlier single-row store (`srijan.state`) is copied over; that table is
 * left as it was, as a backup.
 */
export async function ensureSchema(sql: postgres.Sql, initialDb: () => DB) {
  await sql.begin(async (tx) => {
    // Several server copies may start at once: let one set up while the others wait.
    await tx`select pg_advisory_xact_lock(724110)`;
    await tx`create schema if not exists srijan`;
    await tx`create table if not exists srijan.meta (id int primary key, version int not null, seq int not null, updated_at timestamptz not null default now())`;
    await tx`alter table srijan.meta enable row level security`;
    for (const [, t] of ENTRIES) {
      const cols = t.columns.map(([c, type, expr]) => `${c} ${type} generated always as (${expr}) stored`).join(", ");
      await tx.unsafe(`create table if not exists srijan.${t.name} (id text primary key, ${cols}, data jsonb not null, ord bigserial not null)`);
      await tx.unsafe(`alter table srijan.${t.name} enable row level security`);
    }
    const [meta] = await tx`select 1 from srijan.meta where id = 1`;
    if (meta) return;
    let db = initialDb();
    const [old] = await tx`select to_regclass('srijan.state') is not null as exists`;
    if (old?.exists) {
      const [row] = await tx`select data from srijan.state where id = 1`;
      if (row) db = parse<DB>(row.data);
    }
    await tx`insert into srijan.meta (id, version, seq) values (1, ${db.version}, ${db.seq})`;
    await save(tx, emptySnapshot(), db, { version: db.version, seq: db.seq });
  });
}

/** Locks the store for this transaction and loads everything, in the order it was added. */
export async function load(tx: Tx): Promise<{ db: DB; snapshot: Snapshot; meta: { version: number; seq: number } }> {
  const [meta] = await tx`select version, seq from srijan.meta where id = 1 for update`;
  if (!meta) throw new Error("srijan.meta is missing its row");
  const lists = await Promise.all(ENTRIES.map(([, t]) => tx.unsafe(`select data from srijan.${t.name} order by ord`)));
  const db = { version: meta.version, seq: Number(meta.seq) } as DB;
  const snapshot = emptySnapshot();
  ENTRIES.forEach(([field, t], i) => {
    const records = lists[i]!.map((r) => parse<Record<string, unknown>>(r.data));
    (db as unknown as Record<string, unknown>)[field] = records;
    const seen = snapshot.get(field)!;
    for (const r of records) seen.set(String(r[t.key]), JSON.stringify(r));
  });
  return { db, snapshot, meta: { version: meta.version, seq: Number(meta.seq) } };
}

/** Writes the records that were added, changed or removed since `snapshot`. */
// JSON goes in as text (`$1::text::jsonb`): typed as jsonb, the driver would encode the
// already-encoded string a second time and store one long string.
export async function save(tx: Tx, snapshot: Snapshot, db: DB, meta: { version: number; seq: number }) {
  for (const [field, t] of ENTRIES) {
    const before = snapshot.get(field)!;
    const records = ((db[field] as unknown[] | undefined) ?? []) as Record<string, unknown>[];
    // Last one wins if a key appears twice, so one insert never touches a row twice.
    const now = new Map<string, Record<string, unknown>>();
    for (const r of records) now.set(String(r[t.key]), r);
    const changed = [...now].filter(([k, r]) => before.get(k) !== JSON.stringify(r)).map(([k, v]) => ({ k, v }));
    const removed = [...before.keys()].filter((k) => !now.has(k));
    if (removed.length) {
      await tx.unsafe(`delete from srijan.${t.name} where id in (select jsonb_array_elements_text($1::text::jsonb))`, [JSON.stringify(removed)]);
    }
    if (changed.length) {
      // `with ordinality … order by n` gives new rows `ord` values in the order they were added.
      await tx.unsafe(
        `insert into srijan.${t.name} (id, data)
         select e.x->>'k', e.x->'v' from jsonb_array_elements($1::text::jsonb) with ordinality as e(x, n) order by e.n
         on conflict (id) do update set data = excluded.data`,
        [JSON.stringify(changed)],
      );
    }
  }
  if (db.seq !== meta.seq || db.version !== meta.version) {
    await tx`update srijan.meta set seq = ${db.seq}, version = ${db.version}, updated_at = now() where id = 1`;
  }
}

function parse<T>(v: unknown): T {
  return (typeof v === "string" ? JSON.parse(v) : v) as T;
}
